import java.util.Scanner;

public class Main {
    static final int MAXN = 300010;
    static int n, K, mod;
    static int[][] tableDP = new int[MAXN][20];
    static int[] countBitsArr = new int[MAXN];
    static int[] maxPowerArr = new int[MAXN];
    static long[] factArr = new long[MAXN];
    static long[] invFactArr = new long[MAXN];

    static long fastExponentiation(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long binomial(int i, int j) {
        return (factArr[i] * invFactArr[j] % mod) * invFactArr[i - j] % mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        K = sc.nextInt();
        mod = sc.nextInt();

        int totalResult = 0;

        if ((n & 1) == 1) {
            System.out.println(fastExponentiation(K, n));
            sc.close();
            return;
        }

        factArr[0] = 1;
        for (int i = 1; i <= n; i++) {
            factArr[i] = (factArr[i - 1] * i) % mod;
        }

        invFactArr[n] = fastExponentiation(factArr[n], mod - 2);
        for (int i = n - 1; i >= 1; i--) {
            invFactArr[i] = (invFactArr[i + 1] * (i + 1)) % mod;
        }

        for (int i = 1; i <= n; i++) {
            int count = 0;
            for (int j = 0; j <= 18; j++) {
                if (((1 << j) & i) != 0) {
                    count++;
                }
            }
            countBitsArr[i] = count;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 18; j >= 0; j--) {
                if (((1 << j) & i) != 0) {
                    maxPowerArr[i] = 1 << j;
                    break;
                }
            }
        }

        for (int i = 0; i < MAXN; i++) {
            for (int j = 0; j < 20; j++) {
                tableDP[i][j] = 0;
            }
        }
        tableDP[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            if ((n & i) != i) continue;
            int remaining = i ^ maxPowerArr[i];
            for (int mask = remaining; ; mask = (mask - 1) & remaining) {
                int current = mask + maxPowerArr[i];
                int c2 = i ^ current;
                int limit = Math.min(K - 1, countBitsArr[c2]);
                long tmpVal = binomial(i, current);
                for (int j = 0; j <= limit; j++) {
                    tableDP[i][j + 1] = (int)((tableDP[i][j + 1] + (long) tableDP[c2][j] * tmpVal) % mod);
                }
                if (mask == 0) break;
            }
        }

        for (int j = 1; j <= Math.min(countBitsArr[n], K); j++) {
            totalResult = (int)((totalResult + (long) tableDP[n][j] * binomial(K, j) % mod * factArr[j]) % mod);
        }

        totalResult = (int)((fastExponentiation(K, n) - totalResult + mod) % mod);
        System.out.println(totalResult);
        sc.close();
    }
}
